    "ce": "# Path arcs — exported by Manim Formula Editor for ManimCE 0.22.\n# Render at 1920×1080, 60 fps:\n#     manim -r 1920,1080 --fps 60 PathArcs.py PathArcs\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 936 frames, like the editor's video export.\nfrom manim import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass PathArcs(Scene):\n    def construct(self):\n        self.camera.background_color = \"#000000\"\n\n        # before: a+b\n        before = MathTex(r\"a+b\", font_size=192)\n        before_g = _glyphs(before, [\n            (-1.0744, -0.1166, 0.6095, 0.5812), (0.0477, -0.0715, 0.8582, 0.857), (1.133, 0.0457, 0.4923, 0.9085),\n        ])\n        before_g[0].set_color(\"#F4C867\")\n        before_g[2].set_color(\"#58C4DD\")\n        before.set_z_index(1)\n\n        # after: b+a\n        after = MathTex(r\"b+a\", font_size=192)\n        after_g = _glyphs(after, [\n            (-1.1182, 0.0457, 0.4923, 0.9085), (-0.0754, -0.0715, 0.8582, 0.857), (1.0595, -0.1166, 0.6095, 0.5812),\n        ])\n        after_g[0].set_color(\"#58C4DD\")\n        after_g[2].set_color(\"#F4C867\")\n\n        # before: a+b\n        before_2 = MathTex(r\"a+b\", font_size=192)\n        before_2_g = _glyphs(before_2, [\n            (-1.0744, -0.1166, 0.6095, 0.5812), (0.0477, -0.0715, 0.8582, 0.857), (1.133, 0.0457, 0.4923, 0.9085),\n        ])\n        before_2_g[0].set_color(\"#F4C867\")\n        before_2_g[2].set_color(\"#58C4DD\")\n        before_2.set_z_index(1)\n\n        # after: b+a\n        after_2 = MathTex(r\"b+a\", font_size=192)\n        after_2_g = _glyphs(after_2, [\n            (-1.1182, 0.0457, 0.4923, 0.9085), (-0.0754, -0.0715, 0.8582, 0.857), (1.0595, -0.1166, 0.6095, 0.5812),\n        ])\n        after_2_g[0].set_color(\"#58C4DD\")\n        after_2_g[2].set_color(\"#F4C867\")\n\n        # before: a+b\n        before_3 = MathTex(r\"a+b\", font_size=192)\n        before_3_g = _glyphs(before_3, [\n            (-1.0744, -0.1166, 0.6095, 0.5812), (0.0477, -0.0715, 0.8582, 0.857), (1.133, 0.0457, 0.4923, 0.9085),\n        ])\n        before_3_g[0].set_color(\"#F4C867\")\n        before_3_g[2].set_color(\"#58C4DD\")\n        before_3.set_z_index(1)\n\n        # after: b+a\n        after_3 = MathTex(r\"b+a\", font_size=192)\n        after_3_g = _glyphs(after_3, [\n            (-1.1182, 0.0457, 0.4923, 0.9085), (-0.0754, -0.0715, 0.8582, 0.857), (1.0595, -0.1166, 0.6095, 0.5812),\n        ])\n        after_3_g[0].set_color(\"#58C4DD\")\n        after_3_g[2].set_color(\"#F4C867\")\n\n        # 0 s – 1 s: before write\n        self.play(Write(VGroup(*before_g[:])), run_time=1)\n        # 1 s – 1.8 s\n        self.wait(0.8)\n        # 1.8 s – 3.4 s: before → after\n        self.play(\n            ReplacementTransform(before_g[0], after_g[2]),\n            ReplacementTransform(before_g[1], after_g[1]),\n            ReplacementTransform(before_g[2], after_g[0]),\n            run_time=1.6,\n        )\n        # 3.4 s – 4.8 s\n        self.wait(1.4)\n        self.remove(after)\n        # 4.8 s – 5.4 s\n        self.wait(0.6)\n        # 5.4 s – 6.4 s: before_2 write\n        self.play(Write(VGroup(*before_2_g[:])), run_time=1)\n        # 6.4 s – 7.2 s\n        self.wait(0.8)\n        # 7.2 s – 8.8 s: before_2 → after_2\n        self.play(\n            ReplacementTransform(before_2_g[0], after_2_g[2], path_arc=90 * DEGREES),\n            ReplacementTransform(before_2_g[1], after_2_g[1], path_arc=90 * DEGREES),\n            ReplacementTransform(before_2_g[2], after_2_g[0], path_arc=90 * DEGREES),\n            run_time=1.6,\n        )\n        # 8.8 s – 10.2 s\n        self.wait(1.4)\n        self.remove(after_2)\n        # 10.2 s – 10.8 s\n        self.wait(0.6)\n        # 10.8 s – 11.8 s: before_3 write\n        self.play(Write(VGroup(*before_3_g[:])), run_time=1)\n        # 11.8 s – 12.6 s\n        self.wait(0.8)\n        # 12.6 s – 14.2 s: before_3 → after_3\n        self.play(\n            ReplacementTransform(before_3_g[0], after_3_g[2], path_arc=-90 * DEGREES),\n            ReplacementTransform(before_3_g[1], after_3_g[1], path_arc=-90 * DEGREES),\n            ReplacementTransform(before_3_g[2], after_3_g[0], path_arc=-90 * DEGREES),\n            run_time=1.6,\n        )\n        # 14.2 s – 15.6 s\n        self.wait(1.4)\n",
